import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>القص أسرع طريقة لتحسين صورة: يزيل تشتيتات ويضبط التأطير ويغيّر شكل صورة لتناسب حيث ستعيش.</p>\n<p>كل صورة لها نسخة أفضل مخفية بداخلها: لقطة واسعة بسماء فارغة كثيرة تصبح صورة شخصية قوية عندما يُزال الفراغ الزائد، ولقطة شاشة مليئة بأشياء تصبح مقروءة عندما تُقص إلى ما يهم.</p>\n<p>يشرح هذا الدليل كيف يعمل القص وأي نسب تستخدم وكيف تحقق نتائج نظيفة دائمًا: يغطي الأداة والتقنية والأخطاء التي تفسد قصًا جيدًا. وتستطيع ممارسة كل تقنية مجانًا في المتصفح مع <a href=\"/ar/qass-as-suwar/\">قصاص الصور</a>.</p>\n<h2 id=\"what-cropping-does\">ماذا يفعل القص فعلًا؟</h2>\n<p>القص يقطع الأجزاء الخارجية من صورة ويبقي فقط المستطيل الذي تختاره: لا شيء داخل ذلك المستطيل يتغير؛ والبكسلات التي تحتفظ بها هي نفسها تمامًا مثل الأصل.</p>\n<p>ذلك فرق مهم: القص لا يمد ولا يضغط ولا يعيد أخذ عينات من المنطقة المحفوظة، فالجودة داخل الاختيار تبقى مثل الأصل. وما يتغير هو الشكل والملف: صورة مقصوصة لها بكسلات أقل إجمالًا، ما يعني عادة ملفًا أصغر وتكوينًا أضيق.</p>\n<p>فكر في القص كاختيار ما يجب أن ينظر إليه المشاهد: كل ما يبقى خارج الإطار تشتيت تستطيع إزالته.</p>\n<h2 id=\"aspect-ratios-explained\">النسب: شكل قصك</h2>\n<p>النسبة تصف شكل مستطيل كزوج أرقام، مثل 1:1 لمربع أو 16:9 لشاشة عريضة: الأرقام تناسب لا عدد بكسلات.</p>\n<p>قص 1:1 هو مربع، وهو الشكل الذي تستخدمه معظم صور الشخصية ومنشورات إنستغرام: وقص 4:3 أعرض قليلًا من ارتفاعه، ما يناسب صورًا تقليدية ووثائق. وقص 16:9 واسع وسينمائي: يناسب مصغرات فيديو ولافتات مواقع وشرائح عروض، حيث الصورة تحتاج أن تمتد عبر الشاشة.</p>\n<p>ويشمل القصاص إعدادات مسبقة للنسب الشائعة، إضافة إلى وضع حر لأشكال مخصصة: تثبيت نسبة يبقي إطار الاختيار متناسبًا أثناء سحبه.</p>\n<h2 id=\"rule-of-thirds\">قاعدة الأثلاث وشبكة القص</h2>\n<p>يعرض القصاص شبكة قاعدة أثلاث داخل إطار الاختيار: تقسم الإطار إلى تسعة أجزاء متساوية بخطين أفقيين وخطين عموديين.</p>\n<p>الفكرة بسيطة: ضع الشخص على أحد الخطوط أو في إحدى النقاط الأربع حيث تتقاطع: وجه في نقطة تقاطع يشعر بطبيعية أكثر من وجه في المركز تمامًا. والآفاق تذهب في الخط العلوي أو السفلي لا في الوسط: أفق في الوسط يقسم الصورة نصفين ويجعل التكوين يشعر بالتسطح.</p>\n<p>والشبكة دليل لا قانون: استخدمها لمراجعة تأطيرك واكسر القاعدة عندما يعمل الشخص أفضل بوضوح في المركز، مثل مبنى متماثل أو صورة شخصية.</p>\n<h2 id=\"zoom-and-precise-framing\">التكبير والتأطير الدقيق</h2>\n<p>التكبير يتيح تأطير تفصيل صغير داخل صورة كبيرة: تستطيع تكبير الصورة على المسرح ثم سحب إطار الاختيار فوق المنطقة الدقيقة التي تريدها.</p>\n<p>هذا ينفع لصور منتج، حيث تفصيل صغير يجب أن يملأ الإطار، ولوثائق، حيث فقرة واحدة تحتاج العزل عن صفحة كاملة. والتكبير لا يضيف تفاصيل: يجعل البكسلات الموجودة أكبر على الشاشة فقط لتستطيع وضع إطار القص بدقة، ويبقى الإخراج مستخدمًا الدقة الأصلية.</p>\n<p>اجمع التكبير مع قراءة الأبعاد: تعرض الأداة حجم الإخراج الدقيق بالبكسلات قبل التنزيل، فتستطيع تأكيد أن القص كبير بما يكفي لوجهته.</p>\n<h2 id=\"crop-quality-and-formats\">الجودة والصيغ وما يُحفظ</h2>\n<p>القص يحافظ على الجودة داخل الاختيار، لكن صيغة التصدير ما زالت مهمة: JPG يستخدم ضغطًا فاقدًا، فمنزلق الجودة يتحكم في كم تفصيل ينجو.</p>\n<p>PNG دون فقدان ويحافظ على كل بكسل بالضبط، ما يجعله الخيار الصحيح للقطات شاشة وشعارات ورسوم بنص حاد: ويختفي منزلق الجودة لتصديرات PNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره. وWebP يوفر نقطة وسط: ملفات أصغر من PNG بجودة قريبة: ويحافظ أيضًا على الشفافية، ما يهم عندما تقص شعارًا أو ملصقًا.</p>\n<p>وقص PNG أو WebP شفاف يحافظ على الشفافية داخل الاختيار: تبقى الخلفية شفافة، وهو أمر أساسي للتراكبات والملصقات.</p>\n<h2 id=\"cropping-for-profiles\">كيف تقص لصور شخصية وصور رمزية</h2>\n<p>صور الشخصية دائمًا تقريبًا مربعة، ومعظم المنصات تقصها في دائرة: ذلك يعني أن زوايا مربعك ستُقص، فأبقِ الوجه داخل الإطار جيدًا.</p>\n<p>قص أولًا إلى 1:1، مع الوجه ممركزًا ومساحة قليلة أعلاه: ثم راجع المعاينة الدائرية إذا وفرت منصتك واحدة، واضبط بحيث لا شيء مهم يلمس الحافة. واستخدم الصورة الأصلية لا نسخة مضغوطة: صورة شخصية تُعرض صغيرة، لكن مصدرًا ناعمًا يبقى ناعمًا، وقص حاد من أصل جيد يبدو نظيفًا بأي حجم.</p>\n<p>ولملفات احترافية، قص حتى الرأس والكتفين: لقطة واسعة بوجه صغير تهدر مساحة العرض الصغيرة وتجعل التعرف على الشخص صعبًا.</p>\n<h2 id=\"cropping-for-social-media\">كيف تقص لوسائل التواصل الاجتماعي واللافتات</h2>\n<p>كل منصة لها شكلها المفضل: قص 16:9 يناسب مصغرة فيديو أو غلاف فيسبوك، بينما قص 4:5 يناسب منشورًا عموديًا يملأ شاشة الهاتف.</p>\n<p>راجع قواعد المنصة قبل القص: لافتة مقصوصة بنسبة خطأ ستُمد أو تُعاد قصها بواسطة المنصة، والنتيجة نادرًا ما تكون ممتعة. وأبقِ المحتوى المهم في مركز الإطار: المنصات غالبًا تعيد قص الحواف مجددًا لأحجام شاشة مختلفة، فأي شيء قرب الحافة قد يختفي.</p>\n<p>وعندما يجب أن تخدم صورة منصات عدة، قص من الأصل في كل مرة: قص واحد ممد ليناسب نسبة أخرى سيشوه الصورة، بينما قصاصات جديدة من الأصل تبقى حادة.</p>\n<h2 id=\"cropping-documents-and-screenshots\">كيف تقص وثائق ولقطات شاشة</h2>\n<p>لقطات الشاشة غالبًا تحتوي أكثر مما يلزم: شريط متصفح أو شريط مهام أو هامش فارغ: قص كل ذلك يجعل الجزء المهم أكبر وأسهل قراءة.</p>\n<p>الصق لقطة شاشة مباشرة في القصاص بـCtrl+V: تستطيع قصها فورًا دون حفظ الملف أولًا، ما يوفر خطوة عندما توثق خطأ أو ضبطًا. ولوثائق، قص حتى الفقرة أو الجدول الذي يهم: صفحة كاملة مصغرة إلى صورة صغيرة تصبح غير مقروءة، بينما قص ضيق يبقى حادًا.</p>\n<p>وصدّر لقطات الشاشة كـPNG: الصيغة دون فقدان تحافظ على النص حادًا، بينما ضغط JPG يضبب حواف الحروف ويجعل النص الصغير صعب القراءة.</p>\n<h2 id=\"crop-before-compress\">قص قبل الضغط</h2>\n<p>القص قبل الضغط هو حيلة الجودة الأكثر فعالية في عمل الصور: كل بكسل تزيله بيانات لا يحتاج الضاغط إلى حفظها بعد الآن.</p>\n<p>صورة مقصوصة إلى نصف مساحتها تحتاج نحو نصف حجم الملف بنفس الجودة: ذلك يعني أن البكسلات المحفوظة تحصل على حصة أكبر من ميزانية الملف. ولصورة شخصية، قص حتى الرأس والكتفين قبل الضغط: الوجه يحصل على ميزانية ملف أكثر، فيبقى واضحًا حتى بحجم ملف صغير.</p>\n<p>وقص دائمًا الأصل لا نسخة مضغوطة أصلًا: القص بعد الضغط يتخلص من الجودة مرتين، بينما القص أولًا يحافظ على أفضل مصدر ممكن.</p>\n<h2 id=\"privacy-and-cropping\">خصوصية: القص يزيل أكثر من بكسلات</h2>\n<p>القص قد يزيل معلومات حساسة من صورة: رقم منزل في الخلفية أو اسم على بطاقة هوية أو وجه على حافة الإطار.</p>\n<p>كل المعالجة تحدث في متصفحك، فالصورة لا تُرفع أبدًا: ذلك مهم عندما تكون الصورة بورتريه شخصيًا أو وثيقة هوية أو لقطة خاصة. وتزيل الأداة أيضًا بيانات GPS EXIF عند التصدير: صورة مقصوصة منزلة من الأداة لا تحمل أي سجل لأين التُقطت.</p>\n<p>والقص لا يحل محل التمويه عندما يبقى التفصيل الحساس داخل المنطقة المحفوظة: إذا بقي وجه أو عنوان في الإطار، استخدم أداة <a href=\"/ar/tammih-wa-tabaksul-as-sura/\">التمويه والتبكسيل</a> لإخفائه.</p>\n<h2 id=\"common-crop-mistakes\">أخطاء شائعة عند القص</h2>\n<p>أكثر خطأ شيوعًا قص ضيق جدًا: وجه بلا مساحة أعلاه يبدو مضغوطًا، وشخص يلمس حافة الإطار يبدو كحادث.</p>\n<p>خطأ آخر قص صورة صغيرة أصلًا حتى تصبح أصغر: قص من صورة بدقة منخفضة قد يقع تحت الحجم الذي تطلبه منصة، والنتيجة تبدو ضبابية عند مدها. وينسى الناس أيضًا مراجعة أبعاد الإخراج: تعرض الأداة الحجم الدقيق بالبكسلات قبل التنزيل، وقص صغير جدًا للافتة سيبدو ضبابيًا عند مده.</p>\n<p>وأخيرًا، لا تقص وتعيد قص نفس JPG مرة بعد مرة: كل حفظ يضيف ضررًا، فعد دائمًا إلى الملف الأصلي عندما تريد قصًا مختلفًا.</p>\n<h2 id=\"crop-workflow-tips\">سير عمل يبقي قصاصاتك نظيفة</h2>\n<p>ابدأ بالملف الأصلي وقرر الوجهة أولًا: صورة شخصية ولافتة وطباعة تحتاج أشكالًا مختلفة، فالنسبة تأتي قبل القص.</p>\n<p>استخدم شبكة قاعدة الأثلاث لوضع الشخص ثم راجع قراءة الأبعاد: إذا كان الإخراج صغيرًا جدًا، وسّع الاختيار أو اختر نسبة أصغر. وراجع القص بالحجم الكامل قبل التنزيل: اقترب من الوجه أو النص وتأكد من أن لا شيء مهم ناعم أو مقصوص.</p>\n<p>واحفظ الملف المقصوص باسم واضح، مثل profile-square.png: قد تحتاج نفس القص مجددًا، واسم واضح يوفر عليك إعادة العمل.</p>\n<h2 id=\"cropping-group-photos\">كيف تقص صورًا جماعية</h2>\n<p>صور المجموعة صعبة القص لأن الشخص واسع وكل شخص يهم: قص شخص من الإطار يغيّر الذكرى التي تحفظها الصورة.</p>\n<p>عندما يجب أن تقص صورة جماعية، أبقِ كل وجه داخل إطار الاختيار: وجه مقصوص نصفين على الحافة يبدو كخطأ، حتى لو كان بقية القص جيدًا. واستخدم نسبة واسعة مثل 16:9 أو 3:2 للمجموعات: قص مربع لمجموعة واسعة يجبرك على الاختيار بين قص أشخاص أو تقليص الجميع إلى حجم صغير.</p>\n<p>وإذا كانت صورة المجموعة واسعة جدًا لوجهتها، فكر في تغيير الحجم بدل القص: تغيير الحجم يبقي الجميع في الإطار، بينما القص يزيل أشخاصًا من الحواف.</p>\n<h2 id=\"cropping-for-print\">كيف تقص للطباعة</h2>\n<p>أحجام الطباعة لها نسبها الخاصة، وقص يتجاهلها ستقصه الطابعة: طباعة 6 في 4 بوصات هي 3:2، بينما طباعة 10 في 8 بوصات هي 5:4.</p>\n<p>راجع نسبة حجم الورق قبل القص للطباعة: صورة مقصوصة إلى 16:9 ستترك أشرطة بيضاء في طباعة 4:3، أو تفقد حوافها بقص الطابعة. والطباعة تحتاج دقة أيضًا لا شكلًا فقط: قص صغير مطبوع بحجم كبير سيبدو ناعمًا، فتأكد من عدد البكسلات إضافة إلى النسبة قبل التنزيل.</p>\n<p>وعند الشك، قص أكبر قليلًا من حجم الطباعة واترك المختبر يقص الزائد: هامش إضافي قليل أأمن من قص بالشكل الدقيق تمامًا.</p>\n<h2 id=\"cropping-vs-resizing\">القص أم تغيير الحجم: ماذا تحتاج؟</h2>\n<p>القص يزيل بكسلات من الحواف، بينما تغيير الحجم يغيّر حجم الصورة كلها: يحلان مشكلتين مختلفتين، وخلطهما يؤدي إلى نتائج سيئة.</p>\n<p>قص عندما يكون التأطير سيئًا: سماء كثيرة أو غريب على الحافة أو شخص صغير جدًا في الإطار: تغيير الحجم لا يستطيع إصلاح التأطير. وغيّر الحجم عندما يكون التأطير جيدًا لكن الملف كبير جدًا أو الأبعاد خطأ: القص لا يستطيع تغيير الحجم العام دون إزالة محتوى.</p>\n<p>واستخدم الاثنين معًا عندما تحتاج صورة تغييرات تأطير وحجم: قص أولًا لتصحيح التكوين ثم غيّر حجم النتيجة المقصوصة إلى الأبعاد الدقيقة التي تحتاجها.</p>\n<h2 id=\"cropping-and-file-size\">القص وحجم الملف</h2>\n<p>صورة مقصوصة غالبًا أصغر من الأصل، لأن بكسلات أقل تبقى: كم أصغر يعتمد على كم تقص وصيغة التصدير.</p>\n<p>قص صورة إلى نصف مساحتها يقلل حجم الملف إلى النصف تقريبًا، بنفس ضبط الجودة: ذلك التوفير يهم عندما يجب أن تناسب الصورة حد رفع. ولحدود صارمة، قص أولًا واضغط بعدها: القص يزيل البكسلات التي لا تحتاجها، ثم يعمل الضاغط مع صورة أصغر تناسب الحد بسهولة أكبر.</p>\n<p>وراجع حجم الملف المنزّل قبل رفعه إلى بوابة: قص ما زال كبيرًا جدًا قد يحتاج تغيير صيغة، مثل JPG بدل PNG، أو ضبط جودة آخر.</p>\n<p>لقص صورة في شكل محدد بعد القص، جرّب أداة <a href=\"/ar/tadweer-zawaya-as-sura/\">تدوير زوايا الصورة</a>. وللنسخة خطوة بخطوة لهذه العملية، راجع <a href=\"/ar/blog/kayfiyya-qass-as-sura/\">كيف تقص صورة</a>، وللنسب اقرأ <a href=\"/ar/blog/nisab-qass-as-suwar-mashruha/\">نسب القص موضحة: 1:1 و4:3 و16:9 ومخصصة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما أفضل نسبة لصورة شخصية؟","answer":"مربع 1:1 هو المعيار، لأن معظم المنصات تعرض صورًا شخصية كمربعات أو دوائر: قص مع الوجه ممركزًا ومساحة أعلاه، لأن الدوائر تقص الزوايا."},{"question":"هل قص صورة يقلل جودتها؟","answer":"لا، القص لا يغيّر البكسلات داخل الاختيار: تبقى المنطقة المحفوظة حادة مثل الأصل. وما يتغير هو الحجم الكلي: تبقى بكسلات أقل، فالملف أصغر، لكن الجودة داخل الاختيار لا تتغير."},{"question":"كيف أقص صورة لغلاف فيسبوك أو لافتة موقع؟","answer":"استخدم نسبة واسعة مثل 16:9 وأبقِ المحتوى المهم في المركز، لأن المنصات غالبًا تعيد قص الحواف لشاشات الهواتف: راجع قواعد حجم المنصة أولًا قبل القص."},{"question":"هل أستطيع قص لقطة شاشة على هاتفي؟","answer":"نعم، يعمل القصاص بإيماءات لمس على هواتف وأجهزة لوحية، فتستطيع سحب إطار الاختيار بإصبعك: ارفع اللقطة من معرضك أو الصقها، واختر نسبة ونزّل النتيجة."},{"question":"هل أقص قبل ضغط صورة أم بعدها؟","answer":"قص أولًا: كل بكسل تزيله بيانات لا يحتاج الضاغط إلى حفظها، فالمنطقة المحفوظة تحصل على حصة أكبر من ميزانية الملف وتبقى أوضح: قص دائمًا الملف الأصلي لا نسخة مضغوطة."},{"question":"كيف أعرف إن كان قصي كبيرًا بما يكفي لوجهته؟","answer":"يعرض القصاص أبعاد الإخراج الدقيقة بالبكسلات قبل التنزيل: قارن ذلك الرقم بالحجم الذي تطلبه منصتك أو طابعتك. وإذا كان القص صغيرًا جدًا، وسّع إطار الاختيار أو اختر نسبة تحتفظ ببكسلات أكثر."}];
